  .video-container {
    width: 100%;
    max-width: 400px;          /* Chiều rộng tối đa bạn muốn */
    aspect-ratio: 9 / 16;      /* Tỉ lệ dọc */
    background: #000;
    margin: 0 auto;            /* Căn giữa nếu cần */
  }
  .video-container iframe {
    width: 100%;
    height: 100%;
    border: 0;
  }
</style>

